create or replace TABLE KFL_PRODUCTION.DBP_ETL.VIS_TAG_UMS_WG_TMP cluster by (
     MANDANT_ID,
     DAT 
)(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	DAT DATE NOT NULL COMMENT 'Datum, zu dem der Umsatz entstanden ist, im Format YYYY-MM-DD',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Nummer des Warenumschlagsplatzes',
	WG_ID NUMBER(38,0) NOT NULL COMMENT 'ID der Warengruppe',
	ARTHIERTYP_ID NUMBER(38,0) NOT NULL COMMENT 'Artikel - Hierarchie - Typ - ID: kennzeichnet, ob es sich um eine Hierarchie mit zwei- oder dreistelligen Warengruppen  handelt',
	WRG_ID VARCHAR(3) NOT NULL COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	ABT_ID NUMBER(38,0) NOT NULL COMMENT 'Abteilungs ID negativer Zahlenraum: im DWH generierte IDs, positive Werte: aus Stammdatensystem übernommen',
	GJ NUMBER(38,0) NOT NULL COMMENT 'Geschäftsjahr',
	KJMO NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahremonat, Format JJJJMM',
	KJWO NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahreswoche, Format JJJJWW',
	WTAG_ID NUMBER(38,0) NOT NULL COMMENT 'Wochentag ID',
	UMS_NETTO NUMBER(38,4) NOT NULL COMMENT 'Umsatz netto',
	UMS_NETTO_AF NUMBER(38,4) COMMENT 'Aktionsfreier Netto Umsatz auf Ebene Markt / TAG / Warengruppe',
	UMS_NETTO_SA NUMBER(38,4) COMMENT 'Sonderaktion Netto Umsatz auf Ebene Markt / TAG / Warengruppe',
	UMS_NETTO_WVJ NUMBER(38,4) NOT NULL COMMENT 'Umsatz netto Wochentag im Vorjahr',
	UMS_NETTO_AF_WVJ NUMBER(38,4) COMMENT 'Aktionsfreier Netto Umsatz des vergleichbaren Wochentages des Vorjahres auf Ebene Markt / TAG / Warengruppe',
	UMS_NETTO_SA_WVJ NUMBER(38,4) COMMENT 'Sonderaktion Netto Umsatz des vergleichbaren Wochentages des Vorjahres auf Ebene Markt / TAG / Warengruppe',
	UMS_NETTO_WVVJ NUMBER(38,4) NOT NULL COMMENT 'Umsatz netto Wochentag im Vorvorjahr',
	UMS_NETTO_AF_WVVJ NUMBER(38,4) COMMENT 'Aktionsfreier Netto Umsatz des vergleichbaren Wochentages des Vorvorjahres auf Ebene Markt / TAG / Warengruppe',
	UMS_NETTO_SA_WVVJ NUMBER(38,4) COMMENT 'Sonderaktion Netto Umsatz des vergleichbaren Wochentages des Vorvorjahres auf Ebene Markt / TAG / Warengruppe',
	UMS_NETTO_KVJ NUMBER(38,4) NOT NULL COMMENT 'Umsatz netto Kalendertag im Vorjahr',
	UMS_NETTO_AF_KVJ NUMBER(38,4) COMMENT 'Aktionsfreier Netto Umsatz des Kalendertages des Vorjahres auf Ebene Markt / TAG / Warengruppe',
	UMS_NETTO_SA_KVJ NUMBER(38,4) COMMENT 'Sonderaktion Netto Umsatz des Kalendertages des Vorjahres auf Ebene Markt / TAG / Warengruppe',
	UMS_NETTO_KVVJ NUMBER(38,4) NOT NULL COMMENT 'Umsatz netto Kalendertag im Vor-Vorjahr',
	UMS_NETTO_AF_KVVJ NUMBER(38,4) COMMENT 'Aktionsfreier Netto Umsatz des Kalendertages des Vorvorjahres auf Ebene Markt / TAG / Warengruppe',
	UMS_NETTO_SA_KVVJ NUMBER(38,4) COMMENT 'Sonderaktion Netto Umsatz des Kalendertages des Vorvorjahres auf Ebene Markt / TAG / Warengruppe',
	UMS_BRUTTO NUMBER(38,4) NOT NULL COMMENT 'Umsatz brutto',
	UMS_BRUTTO_KVJ NUMBER(38,4) NOT NULL COMMENT 'Umsatz brutto Kalendertag im Vorjahr',
	UMS_BRUTTO_WVJ NUMBER(38,4) NOT NULL COMMENT 'Umsatz Betrag Brutto Wochentag im Vorjahr',
	MENGE_ABSATZ NUMBER(38,3) NOT NULL DEFAULT 0 COMMENT 'Menge in Basismengeneinheit. Stück und Gewichtsartikel gemischt',
	MENGE_ABSATZ_AF NUMBER(38,3) COMMENT 'Menge an verkauften aktionsfreien Artikel auf Ebene Markt / TAG / Warengruppe',
	MENGE_ABSATZ_SA NUMBER(38,3) COMMENT 'Menge an verkauften Artikel in Sonderaktion auf Ebene Markt / TAG / Warengruppe',
	MENGE_ABSATZ_KVJ NUMBER(38,3) NOT NULL DEFAULT 0 COMMENT 'Menge Kalendertag im Vorjahr in Basismengeneinheit. Stück und Gewichtsartikel gemischt',
	MENGE_ABSATZ_AF_KVJ NUMBER(38,3) COMMENT 'Menge an verkauften aktionsfreien Artikel des Kalendertages des Vorjahres auf Ebene Markt / TAG / Warengruppe',
	MENGE_ABSATZ_SA_KVJ NUMBER(38,3) COMMENT 'Menge an verkauften Artikel in Sonderaktion des Kalendertages des Vorjahres auf Ebene Markt / TAG / Warengruppe',
	MENGE_ABSATZ_WVJ NUMBER(38,3) NOT NULL DEFAULT 0 COMMENT 'Menge Wochentag im Vorjahr in Basismengeneinheit. Stück und Gewichtsartikel gemischt',
	MENGE_ABSATZ_AF_WVJ NUMBER(38,3) COMMENT 'Menge an verkauften aktionsfreien Artikel des vergleichbaren Wochentages des Vorjahres auf Ebene Markt / TAG / Warengruppe',
	MENGE_ABSATZ_SA_WVJ NUMBER(38,3) COMMENT 'Menge an verkauften Artikel in Sonderaktion des vergleichbaren Wochentages des Vorjahres auf Ebene Markt / TAG / Warengruppe',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_VIS_TAG_UMSATZ_WG primary key (MANDANT_ID, DAT, NB_ID, WUP_ID, WG_ID, ARTHIERTYP_ID, WRG_ID)
);